    "abstractSummaryId": "The term “jancuk” is part of the dialect of Surabaya people. For Surabaya people known as “Arek Suroboyo” who lives in the neighborhood of kampung kota (the urban village), “jancuk” is the most common word that is used as an expressive language in daily life. However for some people, the word “jancuk” has a negative connotation. This ethnographic study explore how “jancuk” is used and understood by people living in kampung Surabaya who use it as daily communication. Data collected using in-depth interviews and analyzed using three stages of analysis technique suggested by Miles and Huberman: reduction, display...",
