    "abstractSummaryId": "Penelitian ini bertujuan untuk mengetahui gambaran dinamika kelompok dan pembentukan identitas sosial pada geng motor Ghost Night . Metode yang digunakan dalam penelitian ini adalah kualitatif studi kasus. Penelitian ini menggunakan tiga subjek yang tergabung dalam geng motor Ghost Night selama lima tahun. Setelah melakukan observasi, peneliti mengambil data lewat wawancara semi-terstruktur. Hasil penelitian menunjukkan bahwa identitas sosial setiap anggota geng motor Ghost Night dibentuk oleh otoritas untuk kemudian terjadi dinamika internal kelompok geng motor Ghost Night terbentuk. Identitas sosial yang ter...",
