    "keyFindings": [
      "Identitas sosial yang terbentuk setiap anggota kelompok geng motor Ghost Night dipertahankan kelompok dengan penciptaan rasa takut dengan otoritas dalam kelompok.",
      "Oleh sebab itu, setiap anggota geng motor Ghost Night tidak mempunyai keberanian untuk menolak perintah dan melanggar apa yang dikatakan oleh pemimpin kelompok.",
      "Ancaman dan hukuman secara fisik yang dilakukan oleh pemimpin kelompok adalah cara pemimpin kelompok membentuk kelompok geng motor Ghost Night."
    ],
