    "abstractSummaryId": "As time progresses, the participation of women in the workforce is no longer considered taboo. Psychological well-being has become a focal point for experts due to its crucial role for career women. However, achieving it poses a challenge, especially for those with dual roles as employees and spouses/mothers. Efforts to enhance psychological well-being can be achieved through good social support. This research explores the role of work-family conflict as a mediator in the influence of social support on the psychological well-being of career women. The study employed a quantitative cross-sectional approach with...",
