    "abstractSummaryId": "The number of single mothers who must carry out dual roles as housewives and breadwinners is significant. This single-mother status means that dual roles must be fulfilled. This research aims to determine the influence of spiritual intelligence and social support on psychological well-being among single working mothers. The method used in this research is a quantitative approach with multiple linear regression analysis techniques. The sample in this study consisted of single mothers who worked, either due to divorce or widowhood, with a total of 105 respondents selected using purposive sampling. The research r...",
