    "abstractSummaryId": "Watching online videos is becoming an important part of children's media diets. Children particularly like content that is specifically created for YouTube by YouTube personalities. Because these personalities have a large reach and are considered likeable and credible, they have become social media influencers. For advertisers, these influencers are an interesting channel to reach youth. Therefore, influencers often embed persuasive sponsored messages in their videos to earn money. However, there are concerns about this practice because it is not always clear when a video includes advertising. Therefore, in s...",
