      "For children who experienced a strong PSR with the influencer, the understanding that the content had a selling intent did not affect their brand attitudes.",
      "These findings show that a disclosure (if noticed and remembered) can be an effective tool to achieve transparency, but also influences the persuasive outcomes of influencer marketing in online videos."
