    "abstractSummaryId": "Introduction: Remote work was widely promoted in 2020, as a result of the COVID-19 pandemic. However, the effects of remote work on psychological and physical stress responses and presenteeism of workers remain unclear. This research aims to provide empirical evidence of the implications for people and organizations of this new scenario of working from home. Methods: A two-wave panel survey of before and after the pandemic was performed to investigate the effects of remote work on these aspects among office workers. A total of 3,123 office workers from 23 tertiary industries responded to a questionnaire. Parti...",
