    "abstractSummaryId": "The ongoing pandemic of COVID-19 has forced governments to impose a lockdown, and many people have suddenly found themselves having to reduce their social relations drastically. Given the exceptional nature of similar situations, only a few studies have investigated the negative psychological effects of forced social isolation and how they can be mitigated in a real context. In the present study, we investigated whether the amount of digital communication technology use for virtual meetings (i.e., voice and video calls, online board games and multiplayer video games, or watching movies in party mode) during th...",
