    "abstractSummaryId": "Introduction: Previous research often examined gender stereotypes in leadership with ratings on predetermined gendered characteristics concerning leaders' agency and communality (i.e., explicit measures). The aim of the present study was to broaden the understanding of gender stereotypes in leadership by taking more subtle approaches, that focus on what men and women actually ascribe to typical, male, and female leaders and how they implicitly evaluate them. Methods: An online survey collected (a) free associations which reflect social representations (e.g., dominant, empathic), (b) evaluations of the given as...",
