    "abstractSummaryId": "The Covid-19 induced United Kingdom-wide lockdown in 2020 saw choirs face a unique situation of trying to continue without being able to meet in-person. Live networked simultaneous music-making for large groups of singers is not possible, so other \"virtual choir\" activities were explored. A cross sectional online survey of 3948 choir members and facilitators from across the United Kingdom was conducted, with qualitative analysis of open text questions, to investigate which virtual choir solutions have been employed, how choir members and facilitators experience these in comparison to an \"in-person\" choir, and...",
