    "abstractSummaryId": "Background: The COVID-19 pandemic and the multifaceted response strategies to curb its spread both have devastating effects on mental and emotional health. Social distancing, and self-isolation have impacted the lives of students. These impacts need to be identified, studied, and handled to ensure the well-being of the individuals, particularly the students. Aim: This study aims to analyze the role of coping strategies, family support, and social support in improving the mental health of the students by collecting evidence from post COVID-19. Methods: Data was collected from deaf students studying in Chinese u...",
