    "abstractSummaryId": "OBJECTIVE: The psychological condition of healthcare workers since the COVID-19 pandemic has attracted the attention of many studies. However, few have reported on psychosocial problems of primary healthcare workers in the COVID-19 pandemic. This study aimed to examine the mediating roles of social support and resilience in COVID-19-related work stress and symptoms of anxiety and depression. METHODS: A total of 840 primary healthcare workers in 17 community health centers in Guangzhou, China, were recruited from May to July 2021. Data on demographic characteristics, COVID-19-related work stress, social support...",
