    "abstractSummaryId": "Objective:This study explored the psychological and academic effects of studying online from the home vis-à-vis host country during the coronavirus disease 2019 (COVID-19) pandemic in the experience of international students at the University of Warsaw, Poland. Methods:A total of 357 international students from 62 countries (236 in the host country and 121 in the home country) completed an online questionnaire survey 2 months after transition to online learning. We studied students' levels of loneliness, life and academic satisfaction, acculturative stress, academic adjustment, performance, loyalty, and percep...",
