    "abstractSummaryId": "Burnout has been recognized as a serious health problem. In Portugal, before COVID-19 Pandemic, there were strong indicators of high prevalence of burnout in physicians and nurses. However, the Portuguese Health Care Service was able to efficiently respond to the increased demands. This study intends to understand how psychosocial variables might have been protective factors for burnout in physicians and nurses in Portugal. Specifically, we considered several psychosocial variables that have been found to be protective factors for burnout in previous research and we compared their predictive and unique impact...",
