    "abstractSummaryId": "Our hominin ancestors inevitably encountered and likely ingested psychedelic mushrooms throughout their evolutionary history. This assertion is supported by current understanding of: early hominins' paleodiet and paleoecology; primate phylogeny of mycophagical and self-medicative behaviors; and the biogeography of psilocybin-containing fungi. These lines of evidence indicate mushrooms (including bioactive species) have been a relevant resource since the Pliocene, when hominins intensified exploitation of forest floor foods. Psilocybin and similar psychedelics that primarily target the serotonin 2A receptor sub...",
    "methodology": "Survei Kuantitatif (Pemodelan Struktural / Regresi)",
    "sampleContext": "Detail jumlah & karakteristik partisipan tercantum lengkap pada teks penuh artikel DOI",
    "keyFindings": [
      "The socio-cognitive niche was simultaneously a selection pressure and an adaptive response, and was partially constructed by hominins through their activities and their choices.",
      "Therefore, the evolutionary scenario put forward suggests that integration of psilocybin into ancient diet, communal practice, and proto-religious activity may have enhanced hominin response to the socio-cognitive niche, while also aiding in its creation.",
      "In particular, the interpersonal and prosocial effects of psilocybin may have mediated the expansion of social bonding mechanisms such as laughter, music, storytelling, and religion, imposing a systematic bias on the selective environment that favored selec..."
    ],
