    "abstractSummaryId": "With the development of positive psychology, prosocial behavior has received widespread attention from researchers. Some studies have shown that emotion has a significant influence on individual prosocial behavior, but little research has studied the effect of different types of empathy on college students' prosocial behaviors. The current study examined the mediating effects of gratitude among the associations between different types of empathy (perspective-taking, fantasy, empathic concern, and personal distress) and prosocial behavior among Chinese college students. For the study, we used the Prosocial Tend...",
