    "abstractSummaryId": "Coronavirus disease-2019 (COVID-19) pandemic has seriously threatened the global public health security and caused a series of mental health problem. Current research focuses mainly on mental health status and related factors in the COVID-19 pandemic among Chinese university students. Data from 11133 participants was obtained through an online survey. The Patient Health Question-9 (PHQ-9) was used to assess depressive symptoms, the Social Support Rate Scale (SSRS) was used to assess social support. We also used 7-item Generalized Anxiety Disorder Scale (GAD-7) to assess anxiety symptoms. Totally, 37.0% of the...",
