    "abstractSummaryId": "Introduction: Mental health literacy is viewed as a significant factor that may facilitate an individual's pursuit of professional psychological assistance. However, it is important to explore further influencing factors that might underlie this association. This study, employing the framework of the Theory of Planned Behavior (TPB), aims to examine the relationship between mental health literacy and the behavior of seeking professional psychological help, with a focus on the potential mediating roles of perceived stigma and social support in this context. Methods: = 19.65, SD = 1.41) utilizing self-report mea...",
