    "abstractSummaryId": "The aim of this study was to explore the coping resources of hope and sense of coherence, which are rooted in positive-psychology theory, as potential resilience factors that might reduce the emotional distress experienced by adults from three cultural groups in Israel during the chronic-stress situation of a pandemic. The three cultural groups examined were secular Jews, Ultra-Orthodox Jews, and Arabs. We compared these cultural groups during the second wave of the Covid-19 pandemic, just before the Jewish New Year (mid-September 2020) as a second lockdown was announced. Data were gathered from 248 secular Je...",
