    "abstractSummaryId": "Although healthcare workers play a crucial role in helping curb the hazardous health impact of coronavirus disease 2019 (COVID-19), their lives and major functioning have been greatly affected by the pandemic. This study examined the effects of the COVID-19 pandemic on the quality of life (QoL) of Malaysian healthcare workers and its predictive factors. An online sample of 389 university-based healthcare workers completed questionnaires on demographics, clinical features, COVID-19-related stressors, psychological experiences, and perceived social support after the movement lockdown was lifted. All domains of Q...",
