    "abstractSummaryId": "Personal perceptions of self-efficacy are particularly relevant in the field of music performance, which is oriented toward the outward expressions of one's own ability through public performances. Within this context, a number of personal variables, including social support and performance anxiety, have been shown to be associated with musical success and are therefore relevant for research that seeks to understand the four sources of self-efficacy (mastery experiences, vicarious observation, verbal persuasion, physiological states) that are integral components of Bandura's (2002) Social Learning Theory. Prev...",
