    "abstractSummaryId": "The COVID-19 pandemic has subjected most of the world's population to unprecedented situations, like national lockdowns, health hazards, social isolation and economic harm. Such a scenario calls for urgent measures not only to palliate it but also, to better cope with it. According to existential positive psychology, well-being does not simply represent a lack of stress and negative emotions but highlights their importance by incorporating an adaptive relationship with them. Thus, suffering can be mitigated (and transformed into growth) by, among other factors, adopting an attitude of positive reframing, maint...",
