    "abstractSummaryId": "The main aim of this study is to explore the breadth of the inference field and the type of etiopathogenetic contents of symptom explanations provided by the client and therapist in the first two psychotherapy sessions conducted using a systemic approach. Does the therapist use triadic explanations of psychopathology as suggested by her approach? And do clients resort almost exclusively to monadic and dyadic explanations as did the university students in our previous study? What kind of explanations do they propose? The coding system \"1 to 3: from the monad to the triad\" was applied to the transcripts of 25 in...",
