    "abstractSummaryId": "Girls have much lower mathematics self-efficacy than boys, a likely contributor to the underrepresentation of women in STEM. To help explain this gender confidence gap, we examined predictors of mathematics self-efficacy in a sample of 1,007 9th graders aged 13-18 years (54.2% girls). Participants completed a standardized math test, after which they rated three indices of mastery: an affective component (state self-esteem), a meta-cognitive component (self-enhancement), and their prior math grade. Despite having similar grades, girls reported lower mathematics self-efficacy and state self-esteem, and were less...",
