    "abstractSummaryId": "Background: Occupational burnout is a mental health problem that among nurses may lead not only to physical and psychological complications, but also to a decrease in the quality of patient care. Considering the stressful nature of surgery, operating room nurses may be at a greater risk. Therefore, the present study aimed to identifying factors associated with the occupational burnout from the perspective of operating room nurses. Materials and methods: This qualitative study was conducted in Iran in 2021 using conventional content analysis. Sampling was performed using purposeful sampling method with maximum...",
