    "abstractSummaryId": "Meaningful social interactions and regular physical activity are inversely associated with loneliness. Using a mixed-methods research design employing quantitative and qualitative research approaches, this research aimed to explore loneliness, physical activity, friendship, and experiences relating to the COVID-19 pandemic both prior to and during the pandemic. Quantitative data of (1) n = 363 first-year university students assessed in 2018/2019 and of (2) n = 175 individuals aged 18–29 years assessed in 2020 were gathered using independent self-administered online surveys. In addition, (3) n = 4 students were...",
