    "sampleContext": "Tercatat dalam abstrak artikel: n = 363 (lihat detail kriteria sampel pada artikel asli)",
    "keyFindings": [
      "Thus, with regard to feelings of loneliness during the pandemic, being physically active seems to be a small but potentially relevant factor among young individuals.",
      "The qualitative study suggests that first-year university students might buffer the lack of deep friendships and meaningful interactions by building social bonds in team sports.",
      "In times of physical distancing, young individuals vulnerable to loneliness may therefore require special support such as doing sports with physical distance and perceiving connected with their team for instance by digital devices and emotional coping."
    ],
