    "abstractSummaryId": "Prior studies focused on consumer satisfaction and loyalty have brought undeniable benefits to luxury brand marketing but are not sufficient to ensure a long-lasting and profitable customer-brand relationship in the new setting. Brand identity provides a valuable exploration of this issue. However, the current measurement of brand identity is relatively simple, and there is no clear answer to what factors encourage brand identity development. This study attempts to address this gap by dividing the brand identity structure from a multi-dimensional perspective, considering the role of luxury consumer perceived v...",
