    "abstractSummaryId": "BACKGROUND: In a situation of compulsory home isolation enacted by governments at the spreading of the Covid-19 pandemic, the emotional health and well-being of students became a key factor in the successful implementation of distance teaching methodologies in face-to-face education universities. Psychological well-being, an essential factor in preventing academic failure, has been threatened in this serious situation of unprecedented and stressful isolation. The aim of this study is to analyze the students' cognitive-emotional regulation as well as their beliefs and perceptions about the pandemic and this loc...",
