      "Empirical studies are reviewed implicating compassion as a positively valenced affect.",
      "Accordingly, individuals who most enjoy sad musical portrayals experience a pleasurable prosocial affect (compassion), amplified by empathetic engagement (fantasy), while experiencing only nominal levels of unpleasant emotional contagion (commiseration).",
      "It is suggested that this pattern of trait empathy may apply more broadly, accounting for many other situations where spectators experience pleasure when exposed to tragic representations or portrayals."
