    "abstractSummaryId": "There have been recent concerns about an \"epidemic of loneliness\" during the pandemic, given the pervasiveness of loneliness in the population and its harmful effects on health and well-being. Therefore, it is important to establish the correlates of loneliness. The purpose of the current study was to explore how loneliness relates to a construct termed mattering, which is the feeling of being important to other people. Mattering was assessed with multiple measures in the current study (e.g., mattering in general, fears of not mattering, and mattering to peers). A sample of 172 female psychology undergraduate...",
