      "This study integrates knowledge-attitude-behavior (KAB), Theory of Perceived Risk (TPR), Social Identity Theory (SIT), and Theory of Planned Behavior (TPB), along with a comprehensive framework method, to construct an integrated model exploring the impact o...",
